final_template:
AWSTemplateFormatVersion: "2010-09-09"
Description: "Amazon Verified Permissions policy store for a bookstore application with Cedar schema and static policies."

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": { "type": "Long" },
                      "role": { "type": "Entity", "name": "Role" }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": { "type": "Entity", "name": "User" }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "resourceTypes": ["Book"],
                    "principalTypes": ["User"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": { "type": "String" }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "resourceTypes": ["Book"],
                    "principalTypes": ["User"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": { "type": "String" }
                      }
                    }
                  }
                }
              }
            }
          }

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: "/bookstore/policy-store-id"
      Type: String
      Value: !GetAtt BookstorePolicyStore.PolicyStoreId

  AdminViewAnyBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (principal, action, resource)
            when { principal is Bookstore::User && principal.role == Bookstore::Role::"Admin" && action == Bookstore::Action::"View" && resource is Bookstore::Book };

  ForbidAdminBobView:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid (principal, action, resource)
            when { principal == Bookstore::User::"AdminBob" && action == Bookstore::Action::"View" && resource is Bookstore::Book };

  PublisherViewOwnBooks:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (principal, action, resource)
            when { principal is Bookstore::User && principal.role == Bookstore::Role::"Publisher" && resource is Bookstore::Book && resource.owner == principal && action == Bookstore::Action::"View" };

  SpecificUserViewSpecificBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (principal, action, resource)
            when { principal == Bookstore::User::"JaneDoe" && resource == Bookstore::Book::"TheGreatGatsby" && action == Bookstore::Action::"View" };

  CustomerViewPremiumOffers:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            permit (principal, action, resource)
            when { principal is Bookstore::User && principal.role == Bookstore::Role::"Customer" && principal.yearsAsMember >= 2 && action == Bookstore::Action::"ViewWithPremiumOffers" && resource is Bookstore::Book };

  ForbidLowTenureCustomerPremium:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid (principal, action, resource)
            when { principal is Bookstore::User && principal.role == Bookstore::Role::"Customer" && principal.yearsAsMember < 2 && action == Bookstore::Action::"ViewWithPremiumOffers" && resource is Bookstore::Book };

  ForbidNonUSRegion:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: |
            forbid (principal, action, resource)
            when { context.region != "us" && (action == Bookstore::Action::"View" || action == Bookstore::Action::"ViewWithPremiumOffers") && resource is Bookstore::Book };
